//! One client session: each message from stdin dispatched, each answer
//! written to stdout as one line under one lock, and the `list_changed`
//! check (road map 14's MC3, spec §11 MC-4).
//!
//! **What is answered here and what is forwarded.** `initialize` and `ping`
//! never touch the socket, so a client starts with no Frame Job running and a
//! `ping` is answered while a long call holds the app. `tools/list` is the
//! app's when it answers within `LIST_READ_TIMEOUT` and the bundle's
//! snapshot otherwise; it never launches anything (MC-4). `tools/call`
//! launches its own bundle when no socket answers. Anything else is
//! forwarded when the app answers and is `-32601` when it does not.
//!
//! **`list_changed`.** After a list from the snapshot, or a launch, the
//! next forwarded call is followed by a live `tools/list`; when its tools
//! differ from the ones this session was last given — as JSON VALUES, never
//! bytes, since the catalog's key order differs between processes (MC1's
//! B9) — the client is told `notifications/tools/list_changed`.
//!
//! **A launch that never answered** strands the session: its later calls
//! that find no socket answer the stranded sentence and launch nothing, so
//! an instance that started but never bound is not joined by another on
//! every call. The check and the launch are one critical section per
//! session, so concurrent calls that all found no socket launch at most
//! once between them.

use std::io::Write;
use std::path::Path;
use std::sync::{Arc, Mutex};

use serde_json::{json, Value};

use crate::bundle;
use crate::launch::{self, Launched};
use crate::mcp_versions;
use crate::socket::{self, Reach};

/// stdout, behind one lock: one message, one line, flushed.
pub struct Output {
    stdout: Mutex<std::io::Stdout>,
}

impl Default for Output {
    fn default() -> Self {
        Self::new()
    }
}

impl Output {
    pub fn new() -> Output {
        Output {
            stdout: Mutex::new(std::io::stdout()),
        }
    }

    /// Writes `message` as compact JSON and a newline, then flushes.
    pub fn write(&self, message: &Value) {
        let mut line = message.to_string().into_bytes();
        line.push(b'\n');
        let stdout = self.stdout.lock().unwrap_or_else(|e| e.into_inner());
        let mut handle = stdout.lock();
        let _ = handle.write_all(&line).and_then(|()| handle.flush());
    }
}

#[derive(Default)]
struct State {
    /// The tools this session's client was last given.
    last_given: Option<Value>,
    /// A live list is due after the next forwarded call.
    check_due: bool,
    /// The timeout sentence of this session's launch that never answered.
    stranded: Option<String>,
}

/// A client session's state, behind one lock.
pub struct Session {
    state: Mutex<State>,
    /// Held from a call's `stranded` check through its launch, so a call
    /// that waited behind a launch that never answered sees `stranded`
    /// rather than launching a second instance.
    launching: Mutex<()>,
}

impl Default for Session {
    fn default() -> Self {
        Self::new()
    }
}

/// Reads one stdin line: a blank one is skipped; JSON that does not parse
/// is `-32700` and a batch `-32600`, each with a null id; a notification
/// (no `id`) or a response (no `method`) is dropped and never forwarded;
/// every other message is handled on a thread of its own.
pub fn dispatch(line: &[u8], session: &Arc<Session>, out: &Arc<Output>) {
    if line.iter().all(u8::is_ascii_whitespace) {
        return;
    }
    let message: Value = match serde_json::from_slice(line) {
        Ok(message) => message,
        Err(_) => return out.write(&error(Value::Null, -32700, "parse error")),
    };
    let Some(object) = message.as_object() else {
        let text = if message.is_array() {
            "batches are not supported"
        } else {
            "a message must be a JSON object"
        };
        return out.write(&error(Value::Null, -32600, text));
    };
    if !object.contains_key("id") || !object.contains_key("method") {
        return;
    }
    let (session, out) = (Arc::clone(session), Arc::clone(out));
    std::thread::spawn(move || session.handle(message, &out));
}

impl Session {
    pub fn new() -> Session {
        Session {
            state: Mutex::new(State::default()),
            launching: Mutex::new(()),
        }
    }

    fn state(&self) -> std::sync::MutexGuard<'_, State> {
        self.state.lock().unwrap_or_else(|e| e.into_inner())
    }

    /// Answers one request (it has an `id` and a `method`).
    pub fn handle(&self, message: Value, out: &Output) {
        let id = message.get("id").cloned().unwrap_or(Value::Null);
        let Some(method) = message.get("method").and_then(Value::as_str) else {
            return out.write(&error(id, -32600, "the method must be a string"));
        };
        match method {
            "initialize" => out.write(&initialize(id, &message)),
            "ping" => out.write(&result(id, json!({}))),
            "tools/list" => out.write(&self.tools_list(id, &message)),
            "tools/call" => self.tools_call(id, &message, out),
            other => out.write(&forward_other(id, other, &message)),
        }
    }

    fn tools_list(&self, id: Value, message: &Value) -> Value {
        let path = match socket::socket_path() {
            Ok(path) => path,
            Err(reason) => return self.snapshot_list(id, &reason),
        };
        let answers = socket::reach(&path) == Reach::Answers;
        let why = if !answers {
            format!("nothing answers at {}", path.display())
        } else {
            match socket::post(&path, message, Some(socket::LIST_READ_TIMEOUT)) {
                Ok(Some(answer)) => match answer.pointer("/result/tools") {
                    Some(tools) if tools.is_array() => {
                        let mut state = self.state();
                        state.last_given = Some(tools.clone());
                        state.check_due = false;
                        return answer;
                    }
                    _ => format!("Frame Job's tools/list at {} held no tools", path.display()),
                },
                Ok(None) => format!(
                    "Frame Job answered tools/list at {} with no body",
                    path.display()
                ),
                Err(reason) => reason,
            }
        };
        self.snapshot_list(id, &why)
    }

    /// The snapshot's tools, or `-32603` naming the snapshot and `why` the
    /// app did not answer.
    fn snapshot_list(&self, id: Value, why: &str) -> Value {
        let snapshot = bundle::own_bundle().and_then(|bundle| bundle::read_snapshot(&bundle));
        match snapshot {
            Ok(snapshot) => {
                let mut state = self.state();
                state.last_given = Some(snapshot.tools.clone());
                state.check_due = true;
                result(id, json!({"tools": snapshot.tools}))
            }
            Err(reason) => error(
                id,
                -32603,
                &format!(
                    "no tools to list: {reason} ({}); and {why}",
                    bundle::SNAPSHOT_RELATIVE
                ),
            ),
        }
    }

    fn tools_call(&self, id: Value, message: &Value, out: &Output) {
        let path = match socket::socket_path() {
            Ok(path) => path,
            Err(reason) => return out.write(&call_error(id, &reason)),
        };
        match socket::reach(&path) {
            Reach::Answers => {}
            Reach::Unreachable(reason) => return out.write(&call_error(id, &reason)),
            Reach::Absent => {
                let _launching = self.launching.lock().unwrap_or_else(|e| e.into_inner());
                if let Some(sentence) = self.state().stranded.clone() {
                    return out.write(&call_error(id, &sentence));
                }
                let bundle = match bundle::own_bundle() {
                    Ok(bundle) => bundle,
                    Err(reason) => return out.write(&call_error(id, &reason)),
                };
                match launch::ensure_running(&bundle, &path) {
                    Ok(Launched::Started) => self.state().check_due = true,
                    Ok(Launched::AlreadyUp) => {}
                    Err(reason) => {
                        if reason.starts_with(launch::TIMEOUT_OPENING) {
                            self.state().stranded = Some(stranded_sentence(&reason, &path));
                        }
                        eprintln!("framejob-mcp: {reason}");
                        return out.write(&call_error(id, &reason));
                    }
                }
            }
        }
        match socket::post(&path, message, None) {
            Ok(Some(answer)) => out.write(&answer),
            Ok(None) => {
                return out.write(&call_error(id, "Frame Job answered the call with no body"))
            }
            Err(reason) => return out.write(&call_error(id, &reason)),
        }
        self.check_list(&path, out);
    }

    /// After a forwarded call: when a check is due, a live `tools/list`
    /// compared with the last-given tools as JSON values.
    fn check_list(&self, path: &Path, out: &Output) {
        if !self.state().check_due {
            return;
        }
        let ask =
            json!({"jsonrpc": "2.0", "id": "framejob-mcp-list-check", "method": "tools/list"});
        let live = match socket::post(path, &ask, None) {
            Ok(Some(answer)) => answer
                .pointer("/result/tools")
                .filter(|t| t.is_array())
                .cloned(),
            Ok(None) => None,
            Err(reason) => {
                eprintln!("framejob-mcp: the list check: {reason}");
                None
            }
        };
        let mut state = self.state();
        state.check_due = false;
        let Some(live) = live else { return };
        if state.last_given.as_ref() != Some(&live) {
            state.last_given = Some(live);
            out.write(&json!({"jsonrpc": "2.0", "method": "notifications/tools/list_changed"}));
        }
    }
}

fn initialize(id: Value, message: &Value) -> Value {
    let requested = message
        .pointer("/params/protocolVersion")
        .and_then(Value::as_str)
        .unwrap_or("");
    let version = bundle::own_bundle()
        .and_then(|bundle| bundle::read_snapshot(&bundle))
        .map(|snapshot| snapshot.version)
        .unwrap_or_else(|_| "0.0".to_string());
    result(
        id,
        json!({
            "protocolVersion": mcp_versions::negotiate(requested),
            "capabilities": {"tools": {"listChanged": true}},
            "serverInfo": {"name": "framejob", "version": version},
        }),
    )
}

/// Any method but the four above: the app's answer when it answers.
fn forward_other(id: Value, method: &str, message: &Value) -> Value {
    let Ok(path) = socket::socket_path() else {
        return error(id, -32601, &format!("method not found: {method}"));
    };
    if socket::reach(&path) != Reach::Answers {
        return error(id, -32601, &format!("method not found: {method}"));
    }
    match socket::post(&path, message, None) {
        Ok(Some(answer)) => answer,
        Ok(None) => error(id, -32603, "Frame Job answered with no body"),
        Err(reason) => error(id, -32603, &reason),
    }
}

/// The sentence a stranded session's later calls answer.
fn stranded_sentence(timeout: &str, socket: &Path) -> String {
    let folder = socket.parent().unwrap_or(Path::new("/"));
    format!(
        "{timeout}; that instance may still be running, so this session will not launch \
         another — quit it and check {}",
        folder.display()
    )
}

fn result(id: Value, result: Value) -> Value {
    json!({"jsonrpc": "2.0", "id": id, "result": result})
}

fn error(id: Value, code: i64, message: &str) -> Value {
    json!({"jsonrpc": "2.0", "id": id, "error": {"code": code, "message": message}})
}

/// A proxy-side failure of a `tools/call`, as the CallToolResult a client
/// shows the model.
fn call_error(id: Value, sentence: &str) -> Value {
    result(
        id,
        json!({"content": [{"type": "text", "text": sentence}], "isError": true}),
    )
}
//! Launching Frame Job for a `tools/call` that found no socket (spec §11
//! MC-4): its own bundle, in the background (`open -n -g`), at most one
//! instance between all the proxies that find no socket at once.
//!
//! **The lock.** `agent.launch.lock` beside the socket, taken with
//! `File::lock` (exclusive, blocking) before the re-check and **held until
//! the poll ends**: released before the poll, a second proxy's re-check
//! would find nothing answering yet and launch a second instance. A proxy
//! that waited on the lock re-checks and finds the first one's instance.
//!
//! **A scratch socket** (`RC_AGENT_SOCKET` set, MC-6) is passed to the
//! instance with `open --env`, with `-ApplePersistenceIgnoreState YES` and
//! its stderr written to `framejob-launch.log` beside the socket; the
//! person's own socket gets none of these, so their Frame Job opens as theirs.

use std::ffi::OsString;
use std::fs::{DirBuilder, OpenOptions};
use std::os::unix::fs::{DirBuilderExt, OpenOptionsExt};
use std::path::Path;
use std::process::Command;
use std::time::{Duration, Instant};

use crate::socket::{self, Reach};

/// Overrides the wait for a launched instance, in whole seconds.
pub const WAIT_ENV: &str = "RC_MCP_LAUNCH_WAIT";
/// MC1's wait: a cold launch measured about a second.
pub const DEFAULT_WAIT_SECS: u64 = 60;
/// The launch lock's name, beside the socket.
pub const LOCK_NAME: &str = "agent.launch.lock";
/// A scratch launch's stderr, beside the socket.
pub const LAUNCH_LOG_NAME: &str = "framejob-launch.log";
/// How every timeout sentence begins (`Session` recognises one by it).
pub const TIMEOUT_OPENING: &str = "Frame Job did not answer at ";
/// How often the wait asks the socket.
const POLL: Duration = Duration::from_millis(50);

/// A positive whole number of seconds in `RC_MCP_LAUNCH_WAIT`, else 60 s.
pub fn launch_wait() -> Duration {
    let seconds = std::env::var(WAIT_ENV)
        .ok()
        .and_then(|value| value.trim().parse::<u64>().ok())
        .filter(|seconds| *seconds > 0)
        .unwrap_or(DEFAULT_WAIT_SECS);
    Duration::from_secs(seconds)
}

/// The `/usr/bin/open` arguments that launch `bundle` for `socket`. Pure.
pub fn open_arguments(bundle: &Path, socket: &Path, scratch: bool) -> Vec<OsString> {
    let mut arguments: Vec<OsString> = vec!["-n".into(), "-g".into()];
    if scratch {
        let mut env = OsString::from(format!("{}=", socket::SOCKET_ENV));
        env.push(socket.as_os_str());
        let folder = socket.parent().unwrap_or(Path::new("/"));
        arguments.push("--env".into());
        arguments.push(env);
        arguments.push("--stderr".into());
        arguments.push(folder.join(LAUNCH_LOG_NAME).into_os_string());
    }
    arguments.push(bundle.as_os_str().to_os_string());
    if scratch {
        arguments.push("--args".into());
        arguments.push("-ApplePersistenceIgnoreState".into());
        arguments.push("YES".into());
    }
    arguments
}

/// The sentence a launch that never bound answers.
pub fn timeout_sentence(socket: &Path, wait: Duration, bundle: &Path) -> String {
    format!(
        "{TIMEOUT_OPENING}{} within {} s of launching {}",
        socket.display(),
        wait.as_secs(),
        bundle.display()
    )
}

/// Whether the socket answered at once or after a launch.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Launched {
    AlreadyUp,
    Started,
}

/// Makes sure something answers at `socket`, launching `bundle` if
/// nothing does once the lock is held. The error is a sentence; a launch
/// that never answered is `timeout_sentence`'s.
pub fn ensure_running(bundle: &Path, socket: &Path) -> Result<Launched, String> {
    let folder = socket
        .parent()
        .ok_or_else(|| format!("the socket path {} has no folder", socket.display()))?;
    if !folder.exists() {
        DirBuilder::new()
            .recursive(true)
            .mode(0o700)
            .create(folder)
            .map_err(|e| format!("could not make {}: {e}", folder.display()))?;
    }
    let lock_path = folder.join(LOCK_NAME);
    let lock = OpenOptions::new()
        .read(true)
        .write(true)
        .create(true)
        .truncate(false)
        .mode(0o600)
        .open(&lock_path)
        .map_err(|e| format!("could not open {}: {e}", lock_path.display()))?;
    lock.lock()
        .map_err(|e| format!("could not lock {}: {e}", lock_path.display()))?;
    match socket::reach(socket) {
        Reach::Answers => return Ok(Launched::AlreadyUp),
        Reach::Unreachable(reason) => return Err(reason),
        Reach::Absent => {}
    }
    let arguments = open_arguments(bundle, socket, socket::is_scratch());
    let opened = Command::new("/usr/bin/open")
        .args(&arguments)
        .output()
        .map_err(|e| format!("could not run /usr/bin/open: {e}"))?;
    if !opened.status.success() {
        return Err(format!(
            "/usr/bin/open {} failed ({}): {}",
            bundle.display(),
            opened.status,
            String::from_utf8_lossy(&opened.stderr).trim()
        ));
    }
    let wait = launch_wait();
    let started = Instant::now();
    loop {
        if socket::reach(socket) == Reach::Answers {
            drop(lock);
            return Ok(Launched::Started);
        }
        if started.elapsed() >= wait {
            drop(lock);
            return Err(timeout_sentence(socket, wait, bundle));
        }
        std::thread::sleep(POLL);
    }
}
//! The agent server's socket, from the proxy's side: where it is (spec §11
//! MC-1, MC-6), whether something answers there, and one HTTP/1.1 POST over
//! it. The app's server is `tiny_http` 0.12 (`core/src/agent.rs`), which
//! answers a body of 32 768 bytes or more CHUNKED, and a `tools/list` is
//! about 240 KB, so the reader decodes both `Content-Length` and chunked
//! bodies (and reads to the close when a response has neither).

use std::io::{BufRead, BufReader, ErrorKind, Read, Write};
use std::os::unix::net::UnixStream;
use std::path::{Path, PathBuf};
use std::time::Duration;

use serde_json::Value;

/// Overrides the socket path, for the app and the proxy alike (MC-6).
pub const SOCKET_ENV: &str = "RC_AGENT_SOCKET";

/// How long a forwarded `tools/list` may wait for the app before the
/// snapshot answers instead: the app serves one request at a time, so
/// another client's long call holds it.
pub const LIST_READ_TIMEOUT: Duration = Duration::from_secs(5);

/// The largest response body the reader takes (the app's own request cap).
const MAX_BODY_BYTES: usize = 8 * 1024 * 1024;

/// `RC_AGENT_SOCKET` when set and not empty, else
/// `$HOME/Library/Application Support/Frame Job/Agent/agent.sock` (MC-1).
pub fn socket_path() -> Result<PathBuf, String> {
    if let Some(path) = std::env::var_os(SOCKET_ENV).filter(|path| !path.is_empty()) {
        return Ok(PathBuf::from(path));
    }
    let home = std::env::var_os("HOME")
        .filter(|home| !home.is_empty())
        .ok_or_else(|| "HOME is not set, so the agent socket's path is unknown".to_string())?;
    Ok(PathBuf::from(home).join("Library/Application Support/Frame Job/Agent/agent.sock"))
}

/// True when `RC_AGENT_SOCKET` is set and not empty: a scratch instance,
/// which a launch tells where to bind (MC-6).
pub fn is_scratch() -> bool {
    std::env::var_os(SOCKET_ENV).is_some_and(|path| !path.is_empty())
}

/// What a connect to the socket found.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Reach {
    /// Something accepted the connection.
    Answers,
    /// No file at the path, or a file nothing listens on (a quit's or a
    /// crash's leftover): Frame Job is not running there.
    Absent,
    /// Anything else, in a sentence.
    Unreachable(String),
}

/// Connects to `path` and closes at once.
pub fn reach(path: &Path) -> Reach {
    match UnixStream::connect(path) {
        Ok(_) => Reach::Answers,
        Err(error)
            if matches!(
                error.kind(),
                ErrorKind::NotFound | ErrorKind::ConnectionRefused
            ) =>
        {
            Reach::Absent
        }
        Err(error) => Reach::Unreachable(format!(
            "could not connect to Frame Job at {}: {error}",
            path.display()
        )),
    }
}

/// POSTs `message` to `/mcp` over the socket and reads the answer: 200 →
/// its body as JSON, 202 → None (a notification's answer), anything else →
/// an error naming the status. `read_timeout` bounds each read (None waits
/// as long as the app takes); a read that times out is an error.
pub fn post(
    path: &Path,
    message: &Value,
    read_timeout: Option<Duration>,
) -> Result<Option<Value>, String> {
    let shown = path.display();
    let mut stream = UnixStream::connect(path)
        .map_err(|e| format!("could not connect to Frame Job at {shown}: {e}"))?;
    stream
        .set_read_timeout(read_timeout)
        .map_err(|e| format!("could not set a read timeout on {shown}: {e}"))?;
    let body = serde_json::to_vec(message).map_err(|e| format!("could not encode: {e}"))?;
    let head = format!(
        "POST /mcp HTTP/1.1\r\nHost: localhost\r\nContent-Type: application/json\r\n\
         Accept: application/json, text/event-stream\r\nContent-Length: {}\r\n\
         Connection: close\r\n\r\n",
        body.len()
    );
    stream
        .write_all(head.as_bytes())
        .and_then(|()| stream.write_all(&body))
        .and_then(|()| stream.flush())
        .map_err(|e| format!("could not write to Frame Job at {shown}: {e}"))?;
    let mut reader = BufReader::new(stream);
    let (status, body) = read_response(&mut reader).map_err(|e| match e.kind() {
        ErrorKind::WouldBlock | ErrorKind::TimedOut => format!(
            "Frame Job did not answer at {shown} within {} s",
            read_timeout.map_or(0, |t| t.as_secs())
        ),
        _ => format!("could not read Frame Job's answer at {shown}: {e}"),
    })?;
    match status {
        200 => serde_json::from_slice(&body)
            .map(Some)
            .map_err(|e| format!("Frame Job's answer at {shown} is not JSON: {e}")),
        202 => Ok(None),
        code => Err(format!("Frame Job answered HTTP {code}")),
    }
}

fn invalid(what: &str) -> std::io::Error {
    std::io::Error::new(ErrorKind::InvalidData, what.to_string())
}

/// One header or chunk-size line, without its CRLF; EOF is an error.
fn read_line(reader: &mut impl BufRead) -> std::io::Result<String> {
    let mut line = Vec::new();
    if reader.read_until(b'\n', &mut line)? == 0 {
        return Err(invalid("the connection closed mid-response"));
    }
    while matches!(line.last(), Some(b'\n' | b'\r')) {
        line.pop();
    }
    String::from_utf8(line).map_err(|_| invalid("a response line is not UTF-8"))
}

/// The status code and the decoded body of one HTTP/1.1 response.
fn read_response(reader: &mut impl BufRead) -> std::io::Result<(u16, Vec<u8>)> {
    let status_line = read_line(reader)?;
    let status = status_line
        .split_whitespace()
        .nth(1)
        .and_then(|code| code.parse::<u16>().ok())
        .ok_or_else(|| invalid("the status line has no code"))?;
    let mut length = None;
    let mut chunked = false;
    loop {
        let line = read_line(reader)?;
        if line.is_empty() {
            break;
        }
        let Some((name, value)) = line.split_once(':') else {
            continue;
        };
        let (name, value) = (name.trim(), value.trim());
        if name.eq_ignore_ascii_case("content-length") {
            length = Some(
                value
                    .parse::<usize>()
                    .map_err(|_| invalid("a bad Content-Length"))?,
            );
        } else if name.eq_ignore_ascii_case("transfer-encoding") {
            chunked = value.to_ascii_lowercase().contains("chunked");
        }
    }
    let body = if chunked {
        read_chunked(reader)?
    } else if let Some(length) = length {
        if length > MAX_BODY_BYTES {
            return Err(invalid("the answer is over 8 MiB"));
        }
        let mut body = vec![0; length];
        reader.read_exact(&mut body)?;
        body
    } else {
        let mut body = Vec::new();
        reader
            .take(MAX_BODY_BYTES as u64 + 1)
            .read_to_end(&mut body)?;
        body
    };
    if body.len() > MAX_BODY_BYTES {
        return Err(invalid("the answer is over 8 MiB"));
    }
    Ok((status, body))
}

/// A chunked body: hex sizes (extensions ignored), each chunk and its CRLF,
/// then the zero chunk and any trailer lines up to the blank one.
fn read_chunked(reader: &mut impl BufRead) -> std::io::Result<Vec<u8>> {
    let mut body = Vec::new();
    loop {
        let line = read_line(reader)?;
        let size = line.split(';').next().unwrap_or("").trim();
        let size = usize::from_str_radix(size, 16).map_err(|_| invalid("a bad chunk size"))?;
        if size == 0 {
            while !read_line(reader)?.is_empty() {}
            return Ok(body);
        }
        if body
            .len()
            .checked_add(size)
            .is_none_or(|end| end > MAX_BODY_BYTES)
        {
            return Err(invalid("the answer is over 8 MiB"));
        }
        let start = body.len();
        body.resize(start + size, 0);
        reader.read_exact(&mut body[start..])?;
        let mut crlf = [0u8; 2];
        reader.read_exact(&mut crlf)?;
        if &crlf != b"\r\n" {
            return Err(invalid("a chunk does not end in CRLF"));
        }
    }
}
//! The bundle this proxy lives in, and the catalog snapshot the build wrote
//! into it (road map 14's MC1 q1: `-RCWriteCatalog` in the "Write Agent
//! Catalog" build phase). A proxy launches only its OWN bundle (MC-4), so a
//! copy of Frame Job launches itself and never another copy.

use std::path::{Path, PathBuf};

use serde_json::Value;

/// Where the build puts the snapshot, relative to the bundle.
pub const SNAPSHOT_RELATIVE: &str = "Contents/Resources/agent-catalog.json";

/// `{version, tools}`: the bundle's short version and its `tools/list`
/// catalog as the app would answer it.
#[derive(Debug, Clone, PartialEq)]
pub struct Snapshot {
    pub version: String,
    pub tools: Value,
}

/// The `.app` that holds this executable as `Contents/Helpers/<name>`,
/// symlinks resolved; anything else is an error naming the executable.
pub fn own_bundle() -> Result<PathBuf, String> {
    let exe = std::env::current_exe()
        .map_err(|e| format!("framejob-mcp cannot find its own executable: {e}"))?;
    let exe = exe
        .canonicalize()
        .map_err(|e| format!("framejob-mcp cannot resolve {}: {e}", exe.display()))?;
    let outside = || {
        format!(
            "framejob-mcp is not inside a Frame Job bundle: {} is not <X>.app/Contents/Helpers/<name>, \
             so there is no Frame Job to launch",
            exe.display()
        )
    };
    let helpers = exe.parent().ok_or_else(outside)?;
    let contents = helpers.parent().ok_or_else(outside)?;
    let app = contents.parent().ok_or_else(outside)?;
    let named = |path: &Path, name: &str| path.file_name().is_some_and(|n| n == name);
    if !named(helpers, "Helpers")
        || !named(contents, "Contents")
        || app.extension().is_none_or(|ext| ext != "app")
    {
        return Err(outside());
    }
    Ok(app.to_path_buf())
}

/// Reads and checks `<bundle>/Contents/Resources/agent-catalog.json`.
pub fn read_snapshot(bundle: &Path) -> Result<Snapshot, String> {
    let path = bundle.join(SNAPSHOT_RELATIVE);
    let shown = path.display();
    let bytes = std::fs::read(&path).map_err(|e| format!("could not read {shown}: {e}"))?;
    let mut value: Value =
        serde_json::from_slice(&bytes).map_err(|e| format!("{shown} is not JSON: {e}"))?;
    let version = value
        .get("version")
        .and_then(Value::as_str)
        .ok_or_else(|| format!("{shown} has no string `version`"))?
        .to_string();
    let tools = value
        .get_mut("tools")
        .filter(|tools| tools.is_array())
        .map(Value::take)
        .ok_or_else(|| format!("{shown} has no array `tools`"))?;
    Ok(Snapshot { version, tools })
}
//! The MCP protocol revisions Frame Job speaks, and how a requested one is
//! answered (road map 14's MC3). One file for two readers: `agent.rs`'s
//! `initialize` and the stdio proxy (`mcp-proxy/`), which includes this
//! file by `#[path]`, so the app and the proxy cannot disagree. It therefore
//! uses `std` alone and names nothing of this crate.

/// Protocol revisions this server implements identically (tools-only
/// servers are unchanged across them).
pub const SUPPORTED_VERSIONS: [&str; 3] = ["2024-11-05", "2025-03-26", "2025-06-18"];

/// The newest revision we know: the answer to a request for any other.
pub const LATEST_VERSION: &str = "2025-06-18";

/// The revision to answer a client that asked for `requested`: the same one
/// when supported, else the newest we know, per the spec's negotiation rule.
pub fn negotiate(requested: &str) -> &'static str {
    SUPPORTED_VERSIONS
        .iter()
        .find(|version| **version == requested)
        .copied()
        .unwrap_or(LATEST_VERSION)
}
